// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        vm.assume(rewardToken != address(c));
        // Ensure totalSupply() is 0 before calling addReward
        assertTrue(c.totalSupply() == 0);
        // Call addReward
        c.addReward(rewardToken);
        // After addReward, totalSupply() should still be 0 (no staking has occurred)
        assertTrue(c.totalSupply() == 0);
    }
}

